insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_art4_v1'
from (values
('117.305.c.1.A',3,'A senior plans a body of work about migration that draws on family photographs, maps and interviews. She is doing what?','["Developing themes that integrate a wide range of visual and cultural sources", "Avoiding research", "Choosing a single source", "Copying a poster"]'::jsonb,0,'Advanced work blends many sources.','original'),
('117.305.c.1.A',3,'What makes a theme suitable for a sustained series of personal artworks?','["It has no meaning", "It is rich enough to support many different visual explorations", "It can be expressed in one mark", "It is copied from a famous series"]'::jsonb,1,'A strong theme supports extended work.','original'),
('117.305.c.1.B',3,'A student compares two portraits, one built from precise outlines and the other from loose patches of tone. Which element of art is the main difference?','["Paper weight", "Frame size", "Line versus value and shape handling", "Signature"]'::jsonb,2,'The approach to line and tone differs.','original'),
('117.305.c.1.B',3,'In a still life, how does texture differ from form?','["Texture is color, form is line", "Form is only for painting", "They are the same", "Texture is surface quality while form is three-dimensional shape"]'::jsonb,3,'Elements describe different aspects.','original'),
('117.305.c.1.C',3,'A designer compares unity and variety in two layouts. The layout with strong unity does what?','["Feels cohesive because its parts relate to one another", "Uses only random shapes", "Lacks any pattern", "Has no repeated qualities"]'::jsonb,0,'Unity ties parts together.','original'),
('117.305.c.1.C',3,'Which pairing shows how the principle of proportion differs from emphasis?','["They are identical", "Proportion concerns relative size of parts while emphasis directs attention", "Proportion is color only", "Emphasis is texture only"]'::jsonb,1,'Principles do different jobs.','original'),
('117.305.c.1.D',3,'A student chooses encaustic wax to express layered, translucent memory. This shows her ability to do what?','["Avoid planning", "Use only one medium forever", "Discriminate between media to express complex visual relationships", "Pick supplies by price"]'::jsonb,2,'Advanced artists match media to ideas.','original'),
('117.305.c.1.D',3,'An artist needs a surface that holds heavy, textured paint. Which choice best discriminates between supports?','["Plastic wrap", "Wet newsprint", "Thin tissue", "A primed canvas or panel"]'::jsonb,3,'Heavy paint needs a sturdy support.','original'),
('117.305.c.2.A',3,'A student produces a series of twelve works that connect her sketchbook research, historical studies and field photographs. This is an example of what?','["A body of artwork that integrates information from varied sources", "A copied series", "A random collection", "One unrelated drawing"]'::jsonb,0,'A body of work shows cohesion.','original'),
('117.305.c.2.A',3,'Which feature distinguishes a body of work from a set of unrelated pieces?','["No planning", "A shared concept or approach linking the pieces", "Different themes", "Random sizes"]'::jsonb,1,'A body of work is unified.','original'),
('117.305.c.2.B',3,'A student writes why her final composition supports her theme better than two earlier drafts. She is doing what?','["Ignoring the theme", "Picking a design at random", "Evaluating and justifying design ideas", "Hiding her process"]'::jsonb,2,'Justification explains decisions.','original'),
('117.305.c.2.B',3,'Which question helps evaluate a design idea?','["Is it the biggest?", "Is it the most expensive?", "Is it the fastest?", "Does this choice clearly support the concept of the artwork?"]'::jsonb,3,'Evaluation measures fit to concept.','original'),
('117.305.c.2.C',3,'An artist wants to incorporate a contemporary advertisement into a political collage. Which action best respects copyright principles?','["Transforming the imagery meaningfully and understanding fair use limits", "Selling prints of the ad", "Removing credits to hide the source", "Reproducing it exactly"]'::jsonb,0,'Transformation and legal awareness matter.','original'),
('117.305.c.2.C',3,'A work enters the public domain when what happens?','["It becomes old and valuable", "Its copyright has expired or never applied", "A museum buys it", "The artist becomes famous"]'::jsonb,1,'Public domain is legal status, not fame.','original'),
('117.305.c.2.D',3,'A series of cracked mirrors in a sculpture conveys a fractured sense of identity. This is an example of what?','["Copying a master", "Following a pattern book", "Communicating thoughts and feelings through original art", "Making a tutorial"]'::jsonb,2,'Original artwork conveys ideas.','original'),
('117.305.c.2.D',3,'What makes artwork effective at communicating an idea?','["Cost of materials only", "Random decoration", "Large size alone", "Intentional choices of imagery, materials and composition that support the idea"]'::jsonb,3,'Intentional choices communicate.','original'),
('117.305.c.2.E',3,'Two seniors co-curate a show combining photography and sculpture. Which practice best supports the collaboration?','["Sharing a clear concept and defined responsibilities", "One person deciding everything", "Skipping the planning", "Working separately without talking"]'::jsonb,0,'Clear roles help collaborators.','original'),
('117.305.c.2.E',3,'A benefit of collaborating on a large public artwork is that it does what?','["Removes feedback", "Combines diverse talents toward a shared vision", "Slows down all progress", "Hides individual ideas"]'::jsonb,1,'Collaboration pools strengths.','original'),
('117.305.c.2.F',3,'An artist creates a series of five prints, each with a slight variation of the same plate. This is an example of what?','["A random doodle", "A single drawing", "Creating artwork in a series using a chosen process", "A photocopy"]'::jsonb,2,'A series explores variation.','original'),
('117.305.c.2.F',3,'Choosing a consistent palette and format across several canvases helps a series do what?','["Hide the theme", "Avoid focus", "Look unrelated", "Read as a unified group"]'::jsonb,3,'Consistency links the series.','original'),
('117.305.c.3.A',3,'A student prepares a report on Abstract Expressionism including major artists and the social context. She is doing what?','["Researching and reporting on a historical period and style", "Ignoring sources", "Making up facts", "Copying a catalog"]'::jsonb,0,'A report presents research.','original'),
('117.305.c.3.A',3,'A good art history report should do which of the following?','["Rely on rumors", "Cite reliable sources and connect works to their historical context", "Skip dates", "Avoid describing artworks"]'::jsonb,1,'Quality research uses credible sources.','original'),
('117.305.c.3.B',3,'A student examines how street art and digital culture influence contemporary painting. She is analyzing what?','["A math graph", "A grammar rule", "The influence of contemporary cultures on artwork", "A weather chart"]'::jsonb,2,'Contemporary culture shapes art.','original'),
('117.305.c.3.B',3,'Which question best evaluates the influence of contemporary culture on an artwork?','["What is the hanging height?", "How heavy is the frame?", "What time was it painted?", "How do the artist''s imagery and methods reflect current social ideas and media?"]'::jsonb,3,'Evaluation looks at ideas and media.','original'),
('117.305.c.3.C',3,'A class partners with a senior center to produce portraits of residents for a public exhibit. This is an example of what?','["A community-based art project", "A private commission", "A solo exhibition", "An exam"]'::jsonb,0,'The project serves the community.','original'),
('117.305.c.3.C',3,'Which is a key responsibility in a community-based art project?','["Working in secret", "Respecting the people and place the project serves", "Ignoring community input", "Avoiding collaboration"]'::jsonb,1,'Community work centers the community.','original'),
('117.305.c.3.D',3,'A senior researches art school admissions, builds a portfolio schedule and contacts local studios. She is doing what?','["Avoiding planning", "Giving up art", "Developing a plan of action for an art career", "Skipping research"]'::jsonb,2,'A plan has concrete steps.','original'),
('117.305.c.3.D',3,'Which activity best supports an entrepreneurial path in art?','["Hiding work", "Avoiding customers", "Ignoring costs", "Building a client base and managing pricing and contracts"]'::jsonb,3,'Business skills support entrepreneurship.','original'),
('117.305.c.4.A',3,'Before curating a student exhibition, a class writes criteria such as originality, craftsmanship and clarity of concept. They are doing what?','["Developing evaluative criteria to justify artistic decisions", "Ignoring standards", "Selecting by popularity", "Choosing randomly"]'::jsonb,0,'Criteria guide justified judgments.','original'),
('117.305.c.4.A',3,'Why are clear evaluative criteria useful in art judgment?','["They remove all debate", "They make decisions consistent and explainable", "They guarantee agreement", "They replace looking"]'::jsonb,1,'Criteria support reasoned evaluation.','original'),
('117.305.c.4.B',3,'A student critiques a mural by moving from description to analysis, interpretation and finally evaluation. Why does this order help?','["It starts with opinion", "It avoids thinking", "It builds judgment on careful observation first", "It skips evidence"]'::jsonb,2,'Evidence precedes judgment.','original'),
('117.305.c.4.B',3,'Which critique statement is an analysis, not an evaluation?','["It is worth a lot", "This is the best piece", "I do not like it", "The diagonal lines lead the eye from the lower left to the figure"]'::jsonb,3,'Analysis explains how parts work together.','original'),
('117.305.c.4.C',3,'An artist writes that her series uses weathered materials to explore memory and loss. This written response is called what?','["An artist''s statement", "A signature", "A caption of dimensions", "A receipt"]'::jsonb,0,'It explains purpose and approach.','original'),
('117.305.c.4.C',3,'Which is a quality of a strong artist''s statement?','["Only the price", "Clear language connecting ideas, materials and process", "Vague jargon", "Only a title"]'::jsonb,1,'Clarity helps viewers.','original'),
('117.305.c.4.D',3,'After a critique, an artist keeps the strong elements of her work but reworks a section that confused viewers. She is doing what?','["Ignoring comments", "Copying another student", "Using critique to plan next steps", "Discarding everything"]'::jsonb,2,'Critique informs direction.','original'),
('117.305.c.4.D',3,'What is the best use of critique feedback?','["Argue with everyone", "Accept every comment", "Reject every comment", "Weigh it against your intent and apply what strengthens the work"]'::jsonb,3,'Thoughtful application improves work.','original'),
('117.305.c.4.E',3,'A college-bound student assembles her best work with a short reflection on her growth. This portfolio shows what?','["Evaluation and analysis of personal work", "Only luck", "Her height", "A random selection"]'::jsonb,0,'Portfolios involve selection and reflection.','original'),
('117.305.c.4.E',3,'Which choice improves an electronic portfolio?','["No titles", "High-quality images, clear organization and brief descriptions", "Random order", "Blurry photos"]'::jsonb,1,'Presentation affects impact.','original'),
('117.305.c.4.F',3,'A student reviews artworks from the Renaissance to the present and writes about differences in aesthetics and historical context. She is doing what?','["Ignoring context", "Counting museums", "Forming conclusions about formal qualities, aesthetics and history", "Copying labels"]'::jsonb,2,'Broad evaluation supports conclusions.','original'),
('117.305.c.4.F',3,'Why is knowing an artwork''s historical context important when drawing conclusions about it?','["It determines the frame", "It affects the weight", "It only helps price it", "It helps explain why the work looks and means what it does"]'::jsonb,3,'Context shapes meaning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
